lib = '''"""Shared helpers for ARC noisy-copy completion tasks."""
from collections import Counter


def background_color(grid):
    """Return the most common cell value in the grid."""
    return Counter(v for row in grid for v in row).most_common(1)[0][0]


def find_blocks(grid, bg=None):
    """Split grid into blocks: lists of consecutive row indices containing non-background cells."""
    if bg is None:
        bg = background_color(grid)
    blocks, cur = [], []
    for r, row in enumerate(grid):
        if any(v != bg for v in row):
            cur.append(r)
        elif cur:
            blocks.append(cur)
            cur = []
    if cur:
        blocks.append(cur)
    return blocks


def best_block_shift(rows_a, rows_b, bg=None, w=None):
    """Best horizontal shift s such that rows_b[c] ~ rows_a[c-s]; ties broken by smaller |s|.

    Cost = in-range differing cells + non-background cells of either block whose
    aligned partner falls outside the grid (an accent cell must be explained).
    """
    if w is None:
        w = len(rows_a[0])
    if bg is None:
        bg = background_color(rows_a)
    def cost(s):
        n = 0
        for ra, rb in zip(rows_a, rows_b):
            for c in range(w):
                j = c - s
                if 0 <= j < w:
                    n += ra[j] != rb[c]
                elif rb[c] != bg:
                    n += 1
            for j in range(w):
                if not (0 <= j + s < w) and ra[j] != bg:
                    n += 1
        return n
    return min(range(-(w - 1), w), key=lambda s: (cost(s), abs(s)))


def complete_incomplete_copy(grid, fill=1, bg=None):
    """Complete the truncated copy of a duplicated noisy pattern block.

    The grid holds two blocks of consecutive non-background rows that are copies
    of one pattern at a (possibly nonzero) horizontal shift. The copy whose accent
    extends less far right in aligned coordinates is incomplete: only its
    background cells right of its own max accent column and aligned to the other
    copy's accent cells are set to `fill`.
    """
    if bg is None:
        bg = background_color(grid)
    b1, b2 = find_blocks(grid, bg)[:2]
    w = len(grid[0])
    s = best_block_shift([grid[r] for r in b1], [grid[r] for r in b2], bg, w)
    mx = lambda blk: max(c for r in blk for c, v in enumerate(grid[r]) if v != bg)
    if mx(b1) < mx(b2) - s:
        inc, com, sgn = b1, b2, 1      # inc[c] ~ com[c+s]
    else:
        inc, com, sgn = b2, b1, -1     # inc[c] ~ com[c-s]
    out = [list(row) for row in grid]
    grow = grid[com[0]]
    limit = mx(inc)
    for r in inc:
        for c in range(limit + 1, w):
            cc = c + sgn * s
            if grid[r][c] == bg and 0 <= cc < w and grow[cc] != bg:
                out[r][c] = fill
    return out
'''
